function bizIco(def,sz){ if(!DEF_ICO[def]) return secIco(bizSec(def),sz); const s=SECSTY[bizSec(def)]||SECSTY.commerce; return '<span class="sico" style="background:'+s[0]+(sz?';width:'+sz+'px;height:'+sz+'px':'')+'"><svg viewBox="0 0 24 24" aria-hidden="true">'+DEF_ICO[def]+'</svg></span>'; }
function secIco(sec,sz){ const s=SECSTY[sec]||SECSTY.commerce; return '<span class="sico" style="background:'+s[0]+(sz?';width:'+sz+'px;height:'+sz+'px':'')+'"><svg viewBox="0 0 24 24" aria-hidden="true">'+s[1]+'</svg></span>'; }
function bizAlertSet(){ const set={}; S.biz.forEach(b=>{ if(b.status!=='active') return;
  if(staffFill(b)<.6||(b.fat||0)>65||(b.arr||0)>0||b.soDays||(b.hist.length>=10&&b.hist.slice(-10).reduce((a,x)=>a+x,0)<0)) set[b.id]=1; }); return set; }

function vHome(){
  const t=tierNow(), cur=D.TIERS[t], nx=D.TIERS[t+1];
  let h=head('Tableau de bord',D.DAYS[wdOf(S.day)]+' '+dateL(S.day)+'.');
  if(tutOn()) h+=tutCard();
  else if(!S.biz.length && S.day<15) h+='<div class="notice info">Dans Sociétés, choisissez une ville, un quartier puis un bâtiment pour établir votre première société.<div class="row" style="margin-top:8px">'+btn('Choisir une ville','tab',{c:'pri',i:'biz'})+'</div></div>';
  h+=d100Card();
  /* alertes compactes */
  const al=rptAlerts().sort((a,b)=>(a.k==='bad'?0:1)-(b.k==='bad'?0:1));
  if(al.length) h+='<section class="alerts" aria-label="À surveiller">'+al.slice(0,3).map(a=>'<div class="al '+a.k+'"><i aria-hidden="true">!</i><span>'+esc(a.m)+'</span></div>').join('')+(al.length>3?'<div class="sub">+ '+(al.length-3)+' autre(s) point(s) dans le rapport.</div>':'')+'</section>';
  /* valeur nette */
  const fl=S.flLast||{}; const rows=Object.entries(fl).map(([k,v])=>({k,in:v.in,out:v.out,net:v.in-v.out})).sort((a,b)=>Math.abs(b.net)-Math.abs(a.net));
  const dnet=rows.reduce((a,r)=>a+r.net,0);
  const f=nx? clamp((S.peakNW-cur.nw)/(nx.nw-cur.nw),0,1) : 1;
  const bd=nwBreakdown(); const pos=Object.entries(bd).filter(e=>e[1]>0.5); const tot=pos.reduce((a,e)=>a+e[1],0)||1;
  h+='<section class="card hero"><div class="row sp"><span class="hl">Valeur nette</span>'+(rows.length?pill((dnet>=0?'▲ ':'▼ ')+signed(dnet,0)+' hier',dnet>=0?'good':'bad'):'')+'</div>'+
    '<b class="hbig num">'+eur(S.nw,0)+'</b></section>';
  /* V1.6.2 : accueil épuré ; le reste passe dans « Plus de détails » */
  let hd='<section class="card hero">'+
    lineChart(S.nwH,{h:110,x0:dateS(1),x1:dateS(S.day),label:'Évolution de la valeur nette'})+
    (nx? '<div class="hstep"><div class="row sp"><span><b>'+cur.n+'</b> → '+nx.n+'</span><span class="num">'+Math.round(f*100)+' %</span></div>'+bar(f,'a')+'<div class="sub">'+eur(nx.nw,0)+' de patrimoine record pour débloquer : '+esc(nx.d.split(',').slice(0,3).join(','))+'…</div></div>' : '<div class="sub">Palier maximal atteint.</div>')+
    '<details class="hdet"><summary>Répartition du patrimoine</summary><div class="stk" style="margin:8px 0 6px">'+pos.map((e,i)=>'<i style="width:'+(e[1]/tot*100).toFixed(2)+'%;background:'+CATCOL[i%9]+'"></i>').join('')+'</div><div class="legend">'+pos.map((e,i)=>'<span><i style="background:'+CATCOL[i%9]+'"></i>'+e[0]+' '+eur(e[1],0)+'</span>').join('')+(bd.Dettes<0?'<span class="neg">Dettes '+eur(bd.Dettes,0)+'</span>':'')+'</div></details></section>';
  /* mes sociétés */
  if(S.biz.length){
    const bad=bizAlertSet(), list=S.biz.slice().sort((a,b)=>(b.last?b.last.net:0)-(a.last?a.last.net:0)), MAX=S.biz.length;
    h+='<div class="sech"><h2>Mes sociétés</h2><button class="lnk" data-a="tab" data-i="biz">Tout voir ('+S.biz.length+') ›</button></div><div class="btiles">'+
      list.slice(0,MAX).map(b=>{ const d=bizDef(b), n=b.last?b.last.net:0;
        return '<button class="btile" data-a="bizopen" data-i="'+b.id+'">'+(bad[b.id]?'<span class="bdot" aria-label="À surveiller"></span>':'')+bizIco(b.def)+'<b>'+esc(b.name)+'</b><small>'+esc(d.n)+' · niv. '+b.lvl+'</small>'+
          (b.status==='active'? '<span class="bnet num '+cls(n)+'">'+(b.last?signed(n,0):'—')+'</span>' : '<span class="bnet sub">Ouverture '+Math.max(0,b.since+b.t-S.day)+' j</span>')+'</button>'; }).join('')+
      (S.biz.length>MAX?'<button class="btile more" data-a="tab" data-i="biz"><b>+ '+(S.biz.length-MAX)+'</b><small>autres sociétés</small></button>':'')+
      '<button class="btile add" data-a="tab" data-i="biz"><span class="sico addi" aria-hidden="true">+</span><b>Créer</b><small>une société</small></button></div>';
  }
  /* bilan compact */
  const tin=rows.reduce((a,r)=>a+r.in,0), tout=rows.reduce((a,r)=>a+r.out,0);
  hd+=card('Bilan du '+(S.flLastDay? dateL(S.flLastDay) : 'jour'), rows.length?
    '<div class="flist">'+rows.slice(0,6).map(r=>'<div><span>'+esc(srcName(r.k))+'</span><b class="num '+cls(r.net)+'">'+signed(r.net,0)+'</b></div>').join('')+
    '<div class="ftot"><span>Total'+(rows.length>6?' ('+rows.length+' lignes)':'')+'</span><b class="num '+cls(tin-tout)+'">'+signed(tin-tout,0)+'</b></div></div>'+
    '<div class="row sp"><span class="sub">Entrées '+eur(tin,0)+' · sorties '+eur(tout,0)+'</span><button class="lnk" data-a="tab" data-i="books">Détail ›</button></div>'
    : '<div class="sub">Aucun flux encore.</div>');
  /* agenda */
  const ev=[]; const e=taxEstimate();
  ev.push(['Échéance fiscale','Dans '+(S.nextTax-S.day)+' j','≈ '+eur(e.total,0)]);
  if(S.bills.length) ev.push(['Vote des lois','Dans '+(S.bills[0].vote-S.day)+' j',S.bills.length+' projets']);
  S.biz.filter(b=>b.up).forEach(b=>ev.push(['Agrandissement : '+b.name,'Dans '+b.up.t+' j','Niv. '+b.up.to]));
  S.projects.forEach(p=>ev.push(['Chantier : '+p.name,'Dans '+p.t+' j','']));
  { const cs=[...new Set(S.biz.map(b=>b.city))], fs=[]; cs.forEach(c=>festNext(c).forEach(x=>{ if(x.on||x.in<=30) fs.push(x); })); fs.sort((a,b)=>a.in-b.in); fs.slice(0,2).forEach(x=>ev.push(['Fête : '+x.f.n+' · '+cityName(x.city),x.on?'En cours':'Dans '+x.in+' j',''])); }
  ev.push(['Bourse',marketsOpen()?'Ouverte aujourd’hui':'Fermée le week-end','']);
  const agenda=card('Agenda','<div class="flist">'+ev.slice(0,6).map(x=>'<div><span><b>'+esc(x[0])+'</b><small>'+esc(x[1])+'</small></span><span class="sub num">'+esc(x[2])+'</span></div>').join('')+'</div>');
  /* objectifs */
  const todo=ACH.filter(a=>!S.ach[a.id]); const done=ACH.length-todo.length;
  const T=Math.min(tierNow(),CHAL.length-1), RP=T===CHAL.length-1&&chAllT(T), RN=RP? ((S.chalR&&S.chalR.n)||0) : 0, CH=RP? chRep(RN) : CHAL[T], chs=S.chal||{}, rok=RP? ((S.chalR&&S.chalR.ok)||{}) : null;
  const chH='<div class="tag" style="margin-top:10px">'+(RP? 'Défis de légende, série '+(RN+1) : 'Défis du palier '+esc(D.TIERS[T].n))+' · prime de '+eur(CH.r,0)+' chacun</div><div class="flist">'+CH.l.map((c,i)=>{ const ok=RP? rok[i] : chs[T+':'+i], v=c.v();
    return '<div><span><b>'+c.t+(ok?' · réussi':'')+'</b><small>'+c.d+'</small>'+(ok?'':bar(Math.max(0,Math.min(1,v/c.g)),'g'))+'</span></div>'; }).join('')+'</div>';
  const ach=card('Objectifs',chH+'<div class="row sp" style="margin-top:10px"><span class="sub">'+done+' / '+ACH.length+' réalisés</span></div>'+bar(done/ACH.length,'g')+
    '<div class="flist" style="margin-top:8px">'+todo.slice(0,3).map(a=>'<div><span><b>'+a.t+'</b><small>'+a.d+'</small></span></div>').join('')+(todo.length?'':'<div class="sub">Tous les objectifs sont atteints.</div>')+'</div><div class="row">'+btn('Voir tous les succès','achall',{c:'sm ghost'})+'</div>');
  const jr=S.journal.slice(-8).reverse();
  const jcard=card('Actualités','<div class="log">'+jr.map(x=>'<div><span class="d">'+dateS(x.d)+'</span><span class="'+x.s+'">'+(x.k==='news'?'<span class="tag" style="margin-right:6px">Actu</span>':x.k==='club'?'<span class="tag" style="margin-right:6px">Club</span>':'')+esc(x.m)+'</span></div>').join('')+'</div>');
  hd+='<div class="grid">'+agenda+ach+'</div>'+jcard;
  const F=S.fcfold||{};
  return h+'<details class="fcd hmore" data-k="hm"'+(F.hm?' open':'')+'><summary><span class="hm-s">Plus de détails</span></summary><div class="hm-b">'+(F.hm? hd : '')+'</div></details>';
}

/* En-tête de la fiche société */
function bizHero(b){
  const d=bizDef(b), sec=bizSec(b.def), st=SECSTY[sec]||SECSTY.commerce, l=b.last;
  let h='<section class="bhero'+(ACT_ART[b.def]?' ill':'')+'" style="--sc:'+st[0]+'">'+actBanner(b.def,'act')+
    '<div class="bh-top">'+bizIco(b.def,56)+'<div class="bh-t"><b>'+esc(d.n)+'</b><small>'+esc(bizAddr(b))+'</small></div><span class="bh-lvl">Niv. '+b.lvl+'</span></div>'+
    '<div class="row" style="gap:6px">'+bizStatus(b)+pill('Valeur '+eur(bizValue(b),0),'')+'</div></section>';
  if(b.status!=='active') return h;
  const cs=csOf(b), fat=fatOf(b), roles=entRoles(b).reduce((a,r)=>a+r[1],0);
  h+='<div class="bstats"><div><span>Profit / j</span><b class="num '+cls(l?l.net:0)+'">'+(l?signed(l.net,0):'—')+'</b></div><div><span>Clients / j</span><b class="num">'+fmtN(clientsOf(b),clientsOf(b)<10?1:0)+'</b></div><div><span>Employés</span><b>'+headcount(b)+' / '+roles+'</b></div></div>';
  let g='<div class="gauge"><div class="row sp"><b>Avis clients</b><span>'+starsHTML(starsOf(b))+' <b class="num">'+fmtStar(starsOf(b))+'</b></span></div></div>'+
    '<div class="gauge"><div class="row sp"><b>Fatigue de l’équipe</b><b class="num">'+Math.round(fat)+'</b></div>'+bar(fat/100,fat>60?'r':fat>30?'a':'g')+'</div>';
  if(isStock(b)){ const cr=cogsRef(b), dd=(b.stock||0)/cr; g+='<div class="gauge"><div class="row sp"><b>Stock</b><b class="num">'+dd.toFixed(1)+' j</b></div>'+bar((b.stock||0)/stockCap(b),dd<1.5?'r':dd<3?'a':'g')+'</div>'; }
  h+='<section class="card" style="padding:14px 16px"><div class="stack">'+g+'</div></section>';
  const qa=[];
  if(isStock(b)) qa.push(['Commander','Remplir le stock','orderstk',false]);
  qa.push([trainReady(b)?'Former':'Formation',trainReady(b)?eur(trainCost(b),0):'dans '+(20-(S.day-b.tr))+' j','train',!trainReady(b)||!headcount(b)]);
  qa.push(['Personnel',headcount(b)+' / '+roles+' postes','jump',false,'bj-eq']);
  qa.push(['Pilotage','prix, horaires, pub','jump',false,'bj-pil']);
  if(qa.length<4) qa.push(['Sécurité',SECN[b.sec||0],'jump',false,'bj-sec']);
  h+='<div class="qacts">'+qa.slice(0,4).map(q=>'<button class="qa" data-a="'+q[2]+'" data-i="'+(q[4]||b.id)+'"'+(q[3]?' disabled':'')+'><b>'+q[0]+'</b><small>'+q[1]+'</small></button>').join('')+'</div>';
  if(b.lvl<MAXLVL&&b.lvl>=bizMaxHere(b)) h+='<button class="btn bigup maxed" disabled>Niveau max à cette adresse (niv. '+b.lvl+')</button>';
  else if(b.lvl<MAXLVL) h+='<button class="btn bigup" data-a="upgrade" data-i="'+b.id+'"'+(b.up?' disabled':'')+'>'+(b.up?'Agrandissement en cours · '+b.up.t+' j':'Améliorer au niv. '+(b.lvl+1)+' <span>'+eur(upgradeCost(b),0)+'</span>')+'</button>';
  return h;
}
ACT.jump=el=>{ const t=document.getElementById(el.dataset.i); if(t) t.scrollIntoView({behavior:'smooth',block:'start'}); };

/* ---------- Planning horaire ---------- */
function planSlots(b,compact){
  const pl=planOf(b), w=slotW(b);
  return '<div class="slots3'+(compact?' cp':'')+'">'+SLOTN.map((n,i)=>'<button class="slt'+(pl.s[i]?' on':'')+'" data-a="setplan" data-i="'+b.id+'" data-j="'+i+'" data-v="'+(pl.s[i]?0:1)+'" aria-pressed="'+(pl.s[i]?'true':'false')+'"><b>'+n+'</b>'+(compact?'':'<small>'+SLOTT[i]+'</small>')+'<span class="dem" aria-label="Affluence '+Math.round(w[i]*100)+' %"><i style="width:'+Math.round(w[i]/Math.max(...w)*100)+'%"></i></span></button>').join('')+'</div>';
}
function planTeams(b){ const pl=planOf(b); return '<div class="seg">'+[[1,'1 équipe'],[2,'2 équipes']].map(x=>'<button class="'+(pl.t===x[0]?'on':'')+'" data-a="setplan" data-i="'+b.id+'" data-j="t" data-v="'+x[0]+'">'+x[1]+'</button>').join('')+'</div>'; }
function planFx(b){ const e=planEff(b), fs=e.F>0.05?'<b class="neg">fatigue +'+e.F.toFixed(2)+' / j</b>':e.F<-0.05?'<b class="pos">repos '+e.F.toFixed(2)+' / j</b>':'fatigue stable';
  return 'Ouvert '+e.H+' h · ventes '+multPct(e.S)+' · salaires '+multPct(e.W)+' · '+fs; }
function planBlock(b){
  if(!planOn(b)) return '<div class="stack"><b>Planning horaire</b><div class="sub">Activité ouverte 24 h/24 (en ligne ou hôtellerie) : équipes en roulement automatique.</div></div>';
  return '<div class="stack" style="grid-column:1/-1"><b>Planning horaire</b>'+planSlots(b)+
    '<div class="row sp"><span class="sub">Organisation</span>'+planTeams(b)+'</div>'+
    '<div class="sub">'+planFx(b)+'.</div>'+
    '<div class="sub">La barre indique l’affluence du créneau. Au-delà des horaires habituels, une seule équipe fait des heures supplémentaires (+10 %) et se fatigue. Deux équipes se relaient : service plus rapide (ventes +6 %), plus de fatigue, mais salaires +30 %.</div></div>';
}
function planCard(){
  const L=S.biz.filter(b=>b.status==='active'&&planOn(b));
  if(!L.length) return '';
  return card('Planning des équipes','<div class="stack">'+L.map(b=>{ const e=planEff(b);
    return '<div class="plrow"><div class="row sp"><div style="min-width:0"><b>'+esc(b.name)+'</b><div class="sub">'+esc(distOf(b).n)+' · fatigue '+Math.round(fatOf(b))+'</div></div>'+planTeams(b)+'</div>'+planSlots(b,true)+
      '<div class="sub">'+e.H+' h · ventes '+multPct(e.S)+' · salaires '+multPct(e.W)+(e.F>0.05?' · <b class="neg">fatigue +'+e.F.toFixed(2)+'/j</b>':'')+'</div></div>'; }).join('')+
    '</div><div class="sub" style="margin-top:8px">Les activités ouvertes 24 h/24 (e-commerce, hôtels…) n’apparaissent pas ici.</div>');
}
