function syncBars(){
  if(!window.IBNative||!document.body) return;
  try{ const m=getComputedStyle(document.body).backgroundColor.match(/\d+/g); if(!m) return;
    const [r,g,b]=m.map(Number), hex='#'+[r,g,b].map(x=>x.toString(16).padStart(2,'0')).join('');
    window.IBNative.setBars(hex,(0.299*r+0.587*g+0.114*b)>140); }catch(e){}
}
