/* ---------- Animations de fluidité ---------- */
const RM = () => { try{ return matchMedia('(prefers-reduced-motion: reduce)').matches; }catch(e){ return false; } };
function replay(el,cls){ if(!el) return; el.classList.remove(cls); void el.offsetWidth; el.classList.add(cls); }
function tweenText(el,from,to,fmt,ms){
  if(!el||RM()||!isFinite(from)||!isFinite(to)||from===to) return;
  const t0=performance.now(); el.textContent=fmt(from);
  const step=now=>{ if(!el.isConnected) return; const k=Math.min(1,(now-t0)/ms), e=1-Math.pow(1-k,3); el.textContent=fmt(from+(to-from)*e); if(k<1) requestAnimationFrame(step); };
  requestAnimationFrame(step);
}
function flyCoins(n){
  if(RM()) return;
  const a=document.querySelector('#t-ctrl .stamp'), b=document.querySelector('#t-kpis .kpi b');
  if(!a||!b) return;
  const ra=a.getBoundingClientRect(), rb=b.getBoundingClientRect();
  for(let i=0;i<n;i++){
    const c=document.createElement('i'); c.className='coin'; document.body.appendChild(c);
    const x0=ra.left+ra.width*(.3+.4*Math.random()), y0=ra.top+ra.height/2, x1=rb.left+18+Math.random()*30, y1=rb.top+rb.height/2;
    const mx=(x0+x1)/2+(Math.random()-.5)*60, my=Math.min(y0,y1)-30-Math.random()*40;
    const an=c.animate([{transform:`translate(${x0-11}px,${y0-11}px) scale(.4)`,opacity:0},{transform:`translate(${mx-11}px,${my-11}px) scale(1.1)`,opacity:1,offset:.45},{transform:`translate(${x1-11}px,${y1-11}px) scale(.7)`,opacity:1}],{duration:620+i*70,delay:i*55,easing:'cubic-bezier(.4,0,.2,1)',fill:'both'});
    an.onfinish=()=>{ c.remove(); if(i===n-1){ const k=document.querySelector('#t-kpis .kpi b'); if(k) replay(k,'bump'); } };
  }
}
{ const _render=render;
  render=function(){
    const was={tab:ui._pt, modal:ui._pm, day:ui._pd, kv:ui._kv};
    _render();
    if(!S){ ui._pt=null; ui._pd=null; ui._kv=null; return; }
    if(ui.tab!==was.tab){ replay($('#view'),'enter'); replay($('#nav'),'navchg'); }
    const mk=ui.modal? ui.modal.type+':'+(ui.modal.id===undefined?'':ui.modal.id) : null;
    if(mk&&mk!==was.modal){ const ov=document.querySelector('#modal-root .ov'); if(ov) replay(ov,'open'); }
    const kv=[S.cash,S.nw];
    if(was.kv&&was.day!==undefined&&was.day!==null&&S.day!==was.day){
      const ks=document.querySelectorAll('#t-kpis .kpi b');
      tweenText(ks[0],was.kv[0],kv[0],v=>eur(v,0),700); tweenText(ks[1],was.kv[1],kv[1],v=>eur(v,0),700);
      replay(document.querySelector('#t-day .daynum'),'tick');
      if(kv[0]>was.kv[0]+0.5) flyCoins(Math.min(8,3+Math.round(Math.log10(kv[0]-was.kv[0]+1))));
    }
    ui._pt=ui.tab; ui._pm=mk; ui._pd=S.day; ui._kv=kv;
  };
}

/* ---------- Écran de démarrage animé ---------- */
function showSplash(){
  if(document.getElementById('splash')||!document.body) return;
  const B=[[8,46,'var(--c1)'],[17,70,'var(--c6)'],[28,38,'var(--c5)'],[37,84,'var(--blue)'],[48,52,'var(--c2)'],[58,64,'var(--c4)'],[68,40,'var(--c3)'],[77,76,'var(--c6)'],[88,50,'var(--c1)']];
  const bld=B.map(([x,h,c],i)=>{
    let w=''; for(let r=0;r<Math.floor((h-10)/12);r++) for(let k=0;k<2;k++) w+='<rect class="sw" x="'+(x+1.6+k*3.6)+'" y="'+(116-h+8+r*12)+'" width="2.4" height="4" rx=".8" style="animation-delay:'+(0.9+((i*7+r*3+k*5)%11)*0.09).toFixed(2)+'s"/>';
    return '<g class="sb" style="animation-delay:'+(0.15+i*0.07).toFixed(2)+'s"><rect x="'+x+'" y="'+(116-h)+'" width="9" height="'+h+'" rx="2" fill="'+c+'"/>'+w+'</g>';
  }).join('');
  const el=document.createElement('div'); el.id='splash'; el.setAttribute('role','presentation');
  el.innerHTML='<div class="sp-sky"><svg class="sp-city" viewBox="0 0 104 120" preserveAspectRatio="xMidYMax meet" aria-hidden="true">'+
    '<circle class="sp-sun" cx="78" cy="40" r="11"/>'+bld+'<rect x="0" y="115" width="104" height="5" rx="2" class="sp-ground"/></svg></div>'+
    '<div class="sp-logo"><span class="sp-coin" aria-hidden="true"></span><b>Idle<br>Business</b><small>Bâtissez votre empire, un jour à la fois</small><div class="sp-load" aria-hidden="true"><i></i></div></div>'+
    '<span class="sp-cl c1" aria-hidden="true"></span><span class="sp-cl c2" aria-hidden="true"></span>'+
    [[12,14],[30,8],[52,20],[70,10],[86,16],[20,30],[64,32],[92,6]].map(([x,y],i)=>'<span class="sp-st" style="left:'+x+'%;top:'+y+'%;animation-delay:'+(0.2+i*0.15).toFixed(2)+'s" aria-hidden="true"></span>').join('');
  document.body.appendChild(el);
  const done=()=>{ if(!el.isConnected||el.classList.contains('out')) return; el.classList.add('out'); setTimeout(()=>el.remove(),450); };
  el.addEventListener('click',done);
  setTimeout(done, RM()? 600 : 2900);
}
if(!window.__noSplash) showSplash();

/* ---------- Sélecteurs dans le thème du jeu (remplacent les menus natifs) ---------- */
function optParts(t){ const m=t.match(/^(.*?)\s*(?:\s:\s|,\s)(.+)$/); return m? [m[1],m[2].charAt(0).toUpperCase()+m[2].slice(1)] : [t,'']; }
function pickSet(sel,v){ if(sel.value===v) return; sel.value=v; sel.dispatchEvent(new Event('change',{bubbles:true})); }
function buildPicker(sel){
  const opts=[...sel.options].map(o=>({v:o.value,t:o.textContent.trim(),dis:o.disabled}));
  const parts=opts.map(o=>optParts(o.t)), rich=parts.some(p=>p[1]);
  const w=document.createElement('div');
  const lab=sel.id? document.querySelector('label[for="'+sel.id+'"]') : null;
  const name=lab? lab.textContent.trim() : '';
  const paint=()=>{
    const cur=sel.value;
    if(rich){
      const two=parts.every(p=>p[1].length<=14);
      w.className='pk-cards'+(two?' two':'');
      w.innerHTML=opts.map((o,i)=>'<button type="button" class="pk-card'+(o.v===cur?' on':'')+'" data-pv="'+esc(o.v)+'" aria-pressed="'+(o.v===cur)+'"'+(o.dis?' disabled':'')+'><span class="pk-ck" aria-hidden="true"></span><b>'+esc(parts[i][0])+'</b>'+(parts[i][1]?'<small>'+esc(parts[i][1])+'</small>':'')+'</button>').join('');
    } else if(opts.length<=4 && opts.every(o=>o.t.length<=12)){
      w.className='seg pk-seg';
      w.innerHTML=opts.map(o=>'<button type="button" class="'+(o.v===cur?'on':'')+'" data-pv="'+esc(o.v)+'" aria-pressed="'+(o.v===cur)+'"'+(o.dis?' disabled':'')+'>'+esc(o.t)+'</button>').join('');
    } else {
      const c=opts.find(o=>o.v===cur)||opts[0];
      w.className='pk-btn-wrap';
      w.innerHTML='<button type="button" class="pk-btn" data-pk-open="1" aria-haspopup="dialog"><span>'+esc(c?c.t:'')+'</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 10l5 5 5-5"/></svg></button>';
    }
  };
  w.addEventListener('click',e=>{
    const b=e.target.closest('[data-pv]'); if(b&&!b.disabled){ e.stopPropagation(); pickSet(sel,b.dataset.pv); paint(); return; }
    if(e.target.closest('[data-pk-open]')){ e.stopPropagation(); openSheet(name,opts,sel.value,v=>{ pickSet(sel,v); paint(); }); }
  });
  paint(); return w;
}
function openSheet(title,opts,cur,onPick){
  const ov=document.createElement('div'); ov.className='psheet-ov';
  ov.innerHTML='<div class="psheet" role="dialog" aria-modal="true" aria-label="'+esc(title||'Choisir')+'"><div class="psheet-grab" aria-hidden="true"></div>'+(title?'<div class="psheet-t">'+esc(title)+'</div>':'')+
    '<div class="psheet-list">'+opts.map(o=>'<button type="button" class="psheet-o'+(o.v===cur?' on':'')+'" data-v="'+esc(o.v)+'"'+(o.dis?' disabled':'')+'><span>'+esc(o.t)+'</span><i aria-hidden="true"></i></button>').join('')+'</div>'+
    '<button type="button" class="psheet-x">Annuler</button></div>';
  const close=()=>{ ov.classList.add('out'); setTimeout(()=>ov.remove(),220); };
  ov.addEventListener('click',e=>{ e.stopPropagation(); const o=e.target.closest('.psheet-o'); if(o&&!o.disabled){ onPick(o.dataset.v); close(); return; } if(e.target===ov||e.target.closest('.psheet-x')) close(); });
  document.body.appendChild(ov);
}
function enhanceSelects(){
  document.querySelectorAll('select:not([data-pk])').forEach(sel=>{
    sel.setAttribute('data-pk','1'); sel.classList.add('pk-native'); sel.tabIndex=-1; sel.setAttribute('aria-hidden','true');
    sel.insertAdjacentElement('afterend',buildPicker(sel));
  });
}
